    this.stage = stage;
    this.completedState = completedState;
    this.externalEffectStatus = 'failed';
    this.externalEffectReceipt = {
      clickAttempted: false,
      reason: 'work-order-already-completed',
      stage,
      confirmationMethod: completedState?.confirmationMethod || 'detail-completed',
    };
